    @Test
    @Order(7)
    void testCapacityExceeded() throws Exception {
        String requestBody = """
                {
                    "roomNumber": "201",
                    "guestName": "Ana Paula",
                    "guestEmail": "ana@example.com",
                    "guestCpf": "55566677788",
                    "checkIn": "2027-04-01",
                    "checkOut": "2027-04-03",
