    }

    @Test
    @Order(8)
    void testInvalidEmail() throws Exception {
        String requestBody = """
                {
                    "roomNumber": "201",
                    "guestName": "Carlos Souza",
                    "guestEmail": "carlosgmail.com",
                    "guestCpf": "99988877766",
